import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Первый сеанс","description":"","frontmatter":{"pageId":"players/getting-started","contentRevision":5},"headers":[],"relativePath":"ru/players/getting-started.md","filePath":"ru/players/getting-started.md"}'),r={name:"ru/players/getting-started.md"};function n(s,a,o,d,h,c){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="первыи-сеанс" tabindex="-1">Первый сеанс <a class="header-anchor" href="#первыи-сеанс" aria-label="Permalink to &quot;Первый сеанс&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol><li>Проверь версию игры, установи Harmony и Rimlink, включи их в списке модов и перезапусти игру.</li><li>Открой <strong>Мультиплеер</strong>, добавь адрес и порт сервера, затем войди способом, разрешённым администратором.</li><li>Сверь новый отпечаток сертификата по независимому каналу. Устрани различия набора модов.</li><li>Создай колонию на общей планете: параметры мира задаёт сервер, выбирай свободное место.</li><li>Дождись появления поселенцев, начни игру. Перед выходом используй обычный выход в главное меню и дождись сохранения/отправки.</li><li>При следующем входе убедись, что сервер загрузил эту колонию. Только после этого начинай передачи и поездки.</li></ol><h2 id="first-evening" tabindex="-1">Первый вечер: от адреса сервера до повторного входа <a class="header-anchor" href="#first-evening" aria-label="Permalink to &quot;Первый вечер: от адреса сервера до повторного входа {#first-evening}&quot;">​</a></h2><p>Подготовь адрес и порт, пароль сервера (если есть), требования к DLC/модам и контакт администратора для проверки сертификата. Пароль сервера открывает доступ к серверу; личный пароль, если такой вход разрешён, относится к твоей учётной записи.</p><ol><li>Убедись, что «Мультиплеер» есть в главном меню. Если нет — сначала закончи установку, не ищи ошибку сети.</li><li>Добавь сервер, проверь отпечаток TLS и выполни вход. Сверку модов пройди до создания колонии.</li><li>Если мир ещё не создан, дождись администратора. Для существующего мира выбери новый сценарий и свободное место на серверной планете.</li><li>После приземления колонистов поставь игру на паузу и проверь имя игрока, домашнюю карту и поселения других игроков.</li><li>Выйди обычной кнопкой в главное меню и дождись сохранения/отправки. Войди на тот же сервер той же учётной записью.</li><li>Должна загрузиться та же колония. Только после этого начинай обмен или визит — так ты заранее проверишь базовую цепочку сохранения.</li></ol><p><strong>Результат:</strong> один аккаунт, одно поселение, серверный сейв, подтверждённый повторной загрузкой. Новое окно создания мира при ожидаемой старой колонии — повод остановиться и сверить сервер/аккаунт, а не создавать замену.</p><h2 id="first-failure" tabindex="-1">Если первый вход не завершился <a class="header-anchor" href="#first-failure" aria-label="Permalink to &quot;Если первый вход не завершился {#first-failure}&quot;">​</a></h2><p>Разделяй этапы: отсутствует меню — установка; нет ответа — адрес/порт/доступность; изменён pin — безопасность; mismatch — сборка; отказ входа — учётная запись; ошибка загрузки — сейв/зависимости. Запиши точный текст и этап. После потерянного соединения не делай другой аккаунт для «возврата» товаров.</p><p>Для первого безопасного обмена отправь небольшое количество обычного ресурса и проверь почту с обеих сторон. Это не нагрузочный тест и не основание отправлять ценных колонистов до проверки сборки.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не закрывай процесс принудительно во время отправки. Вход нового администратора может использоваться для создания мира; обычный игрок не должен создавать отдельную планету в обход серверного мира.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./install">Установка мода</a></li><li><a href="./connect">Подключение и вход</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li></ul>',15)])])}const f=e(r,[["render",n]]);export{u as __pageData,f as default};
